INSERT INTO `v1_3f8e4ee0d33b26c876fb4cf6685c6a1c500c1221167d1904ce7320ee25b16f74` VALUES (1, "", 1, "怖い魔物もたくさんいますけど\n探せばぴにゃこら太さんや\nプチグリフォンさんみたいに\nかわいい魔物もいると思うんですよね！", 3, 10, 11, "", "", 112411, 1030016);
INSERT INTO `v1_3f8e4ee0d33b26c876fb4cf6685c6a1c500c1221167d1904ce7320ee25b16f74` VALUES ("", "", "", "", 3, "", 91, "", "", 0, 1030017);
