INSERT INTO `v1_3f8e4ee0d33b26c876fb4cf6685c6a1c500c1221167d1904ce7320ee25b16f74` VALUES (1, "", 1, "あっ、たしかにそうですね！\nまずは目の前のぴにゃこら太さんに\n認めてもらわなきゃですし♪", 3, 10, 11, "", "", 112411, 1030038);
