INSERT INTO `v1_3f8e4ee0d33b26c876fb4cf6685c6a1c500c1221167d1904ce7320ee25b16f74` VALUES ("", "", 0, "vo_omp_7006_004", 6, 0, 21, "", "", "vo_omp_7006", 1060025);
INSERT INTO `v1_3f8e4ee0d33b26c876fb4cf6685c6a1c500c1221167d1904ce7320ee25b16f74` VALUES (1, "", 1, "あの人にとっては何気ない\n一言だったのかも知れないですけど\n私にはそれがとてもうれしくて", 6, 10, 11, "", "", 112411, 1060026);
INSERT INTO `v1_3f8e4ee0d33b26c876fb4cf6685c6a1c500c1221167d1904ce7320ee25b16f74` VALUES ("", "", "", "", 6, "", 91, "", "", 0, 1060027);
