INSERT INTO `v1_3f8e4ee0d33b26c876fb4cf6685c6a1c500c1221167d1904ce7320ee25b16f74` VALUES (1, "", 1, "だからもっともっと頑張って\n最高のステージをすることで\nその言葉にお返しが\nできたらなって…", 6, 10, 11, "", "", 112411, 1060030);
