INSERT INTO `v1_3f8e4ee0d33b26c876fb4cf6685c6a1c500c1221167d1904ce7320ee25b16f74` VALUES (1, "", 1, "でも、自分たちで立ち上がって\n再び舞台に立つ姿…\nわたくし、感動いたしました", 7, 10, 11, "", "", 105931, 1070041);
